import type { BankQuestion } from "@/lib/bank";

/** The Solar System (Geography): 114 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"geo-solar-system-1","question":"Which is the largest planet in the Solar System?","options":["Saturn","Jupiter","Neptune","Earth"],"answer":1,"explanation":"Jupiter is the largest planet.","difficulty":"easy"},
  {"id":"geo-solar-system-2","question":"Which planet is known as the Red Planet?","options":["Venus","Mars","Jupiter","Mercury"],"answer":1,"explanation":"Iron oxide (rust) on its surface makes Mars look red.","difficulty":"easy"},
  {"id":"geo-solar-system-3","question":"Which planet is closest to the Sun?","options":["Venus","Earth","Mercury","Mars"],"answer":2,"explanation":"Mercury is the closest planet to the Sun.","difficulty":"easy"},
  {"id":"geo-solar-system-4","question":"Which planet is the hottest?","options":["Mercury","Venus","Mars","Jupiter"],"answer":1,"explanation":"Venus is hotter than Mercury because its thick CO₂ atmosphere traps heat.","difficulty":"moderate"},
  {"id":"geo-solar-system-5","question":"Which planet has the most prominent ring system?","options":["Jupiter","Saturn","Uranus","Neptune"],"answer":1,"explanation":"Saturn’s rings, made of ice and rock, are the brightest and most extensive.","difficulty":"moderate"},
  {"id":"geo-solar-system-6","question":"Which planet is often called Earth’s twin because of its similar size and mass?","options":["Mars","Venus","Mercury","Neptune"],"answer":1,"explanation":"Venus is nearly the same size and mass as Earth.","difficulty":"moderate"},
  {"id":"geo-solar-system-7","question":"Which planet rotates almost on its side, with an axial tilt of about 98°?","options":["Saturn","Uranus","Neptune","Mars"],"answer":1,"explanation":"Uranus is tilted about 98°, so it appears to roll along its orbit.","difficulty":"hard"},
  {"id":"geo-solar-system-8","question":"Which is the largest natural satellite in the Solar System?","options":["Titan","Ganymede","The Moon","Europa"],"answer":1,"explanation":"Ganymede, a moon of Jupiter, is larger than the planet Mercury.","difficulty":"hard"},
  {"id":"geo-solar-system-9","question":"Which planet takes the longest to orbit the Sun?","options":["Uranus","Saturn","Neptune","Jupiter"],"answer":2,"explanation":"Neptune, the farthest planet, takes about 165 Earth years for one orbit.","difficulty":"hard"},
  {"id":"geo-solar-system-10","question":"Which planet has the shortest day (fastest rotation)?","options":["Earth","Mars","Jupiter","Mercury"],"answer":2,"explanation":"Jupiter rotates once in just under 10 hours.","difficulty":"very-hard"},
  {"id":"geo-solar-system-11","question":"The asteroid belt lies between the orbits of:","options":["Earth and Mars","Mars and Jupiter","Jupiter and Saturn","Venus and Earth"],"answer":1,"explanation":"Most asteroids orbit in the main belt between Mars and Jupiter.","difficulty":"very-hard"},
  {"id":"geo-solar-system-12","question":"Olympus Mons, the largest volcano in the Solar System, is on:","options":["Venus","Mars","Earth","Io"],"answer":1,"explanation":"Olympus Mons on Mars is about 22 km high, nearly three times the height of Mount Everest.","difficulty":"very-hard"},
  {"id":"geo-solar-system-13","question":"Which planet is called the “Red Planet”?","options":["Venus","Mars","Jupiter","Saturn"],"answer":1,"explanation":"Iron oxide on Mars’s surface gives it a reddish colour.","difficulty":"easy","source":"RRB Group D · SSC CHSL"},
  {"id":"geo-solar-system-14","question":"The hottest planet in the Solar System is:","options":["Mercury","Venus","Mars","Jupiter"],"answer":1,"explanation":"Venus is hotter than Mercury because its thick CO₂ atmosphere traps heat.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-solar-system-15","question":"Which planet is known as the “Morning Star” or “Evening Star”?","options":["Mercury","Venus","Mars","Jupiter"],"answer":1,"explanation":"Venus is bright enough to be seen just before sunrise or after sunset.","difficulty":"moderate","source":"SSC CHSL · RRB Group D"},
  {"id":"geo-solar-system-16","question":"The largest moon in the Solar System, Ganymede, belongs to:","options":["Saturn","Jupiter","Neptune","Uranus"],"answer":1,"explanation":"Ganymede, a moon of Jupiter, is bigger than the planet Mercury.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-solar-system-17","question":"Which planet rotates on its side, with an axial tilt of about 98°?","options":["Venus","Saturn","Uranus","Neptune"],"answer":2,"explanation":"Uranus’s extreme tilt means its poles take turns facing the Sun.","difficulty":"hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-solar-system-18","question":"Which planet takes the longest to complete one revolution around the Sun?","options":["Jupiter","Saturn","Uranus","Neptune"],"answer":3,"explanation":"Neptune, the farthest planet, takes about 165 Earth years per orbit.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"geo-solar-system-19","question":"Which planets have no natural satellite?","options":["Mercury only","Venus only","Both Mercury and Venus","Mars and Venus"],"answer":2,"explanation":"Mercury and Venus have no moons; Mars has two, Phobos and Deimos.","difficulty":"hard"},
  {"id":"geo-solar-system-20","question":"The main asteroid belt lies between the orbits of:","options":["Earth and Mars","Mars and Jupiter","Jupiter and Saturn","Neptune and Pluto"],"answer":1,"explanation":"The asteroid belt is between Mars and Jupiter; the Kuiper belt is beyond Neptune.","difficulty":"hard"},
  {"id":"geo-solar-system-21","question":"Consider: 1. Venus rotates from east to west. 2. A day on Venus is longer than its year. 3. Venus has the highest surface temperature of any planet. Which are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Venus rotates backwards; it takes about 243 Earth days to rotate and 225 to orbit; its CO₂ atmosphere makes it the hottest.","difficulty":"very-hard"},
  {"id":"geo-solar-system-22","question":"By Kepler’s third law, a planet 4 times as far from the Sun as Earth takes how many Earth years to orbit?","options":["4","8","16","64"],"answer":1,"explanation":"T² ∝ a³, so T = 4^(3/2) = 8 years.","difficulty":"very-hard"},
  {"id":"geo-solar-system-23","question":"How many of these statements are correct? I. Jupiter is the largest planet. II. Saturn’s average density is less than that of water. III. Mercury has the most eccentric orbit of the eight planets. IV. Neptune was the first planet found by mathematical prediction.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct; Neptune was predicted by Le Verrier and Adams before it was seen in 1846.","difficulty":"very-hard"},
  {"id":"geo-solar-system-24","question":"How many of these statements are correct? I. Earth is closest to the Sun in early January. II. Seasons are caused mainly by the change in the Earth–Sun distance. III. Earth’s axis is tilted about 23.5° from the perpendicular to its orbit.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and III. Seasons come from the tilt of the axis, not the distance.","difficulty":"very-hard"},
  {"id":"geo-solar-system-25","question":"How many of these statements are correct? I. Venus rotates from east to west. II. Uranus has an axial tilt of about 98°. III. Mars has no natural satellite.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. Mars has two moons, Phobos and Deimos.","difficulty":"very-hard"},
  {"id":"geo-solar-system-26","question":"The Earth is closest to the Sun (perihelion) around:","options":["3 January","4 July","21 June","22 December"],"answer":0,"explanation":"Perihelion falls around 3 January and aphelion around 4 July. Seasons come from the axial tilt, not distance.","difficulty":"very-hard"},
  {"id":"geo-solar-system-27","question":"Assertion (A): The outer planets have much lower densities than the inner planets. Reason (R): The outer planets are made mostly of light gases such as hydrogen and helium.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Saturn’s density is even less than water’s, because the giants are mostly hydrogen and helium.","difficulty":"very-hard"},
  {"id":"geo-solar-system-28","question":"Arrange these planets in order of size, largest first: 1. Neptune 2. Saturn 3. Uranus 4. Earth","options":["2-3-1-4","2-1-3-4","1-2-3-4","2-3-4-1"],"answer":0,"explanation":"Saturn (about 9 Earth radii), then Uranus, which is slightly larger than Neptune though less massive, then Earth.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-solar-system-29","question":"Assertion (A): Mercury has the largest difference between day and night temperatures of any planet. Reason (R): Mercury has almost no atmosphere to retain heat.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Without an atmosphere, heat absorbed by day escapes at night, so the surface swings from about 430 °C to −180 °C.","difficulty":"very-hard"},
  {"id":"geo-solar-system-30","question":"Which is the smallest planet in the Solar System?","options":["Mars","Mercury","Venus","Pluto"],"answer":1,"explanation":"Mercury (diameter about 4,880 km) is the smallest of the eight planets; Pluto is smaller but is a dwarf planet, not a planet.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-solar-system-31","question":"The Sun is made up mainly of which two elements?","options":["Oxygen and nitrogen","Hydrogen and helium","Carbon and oxygen","Helium and neon"],"answer":1,"explanation":"About 73% of the Sun’s mass is hydrogen and about 25% helium; hydrogen fuses into helium in its core.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-solar-system-32","question":"Which planet is called the “Blue Planet”?","options":["Neptune","Uranus","Earth","Venus"],"answer":2,"explanation":"Earth is the Blue Planet because about 71% of its surface is covered by water; Neptune also looks blue but is the “ice giant”.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-solar-system-33","question":"The Great Red Spot, a storm larger than the Earth, is found on:","options":["Mars","Saturn","Jupiter","Neptune"],"answer":2,"explanation":"The Great Red Spot is a giant anticyclonic storm in Jupiter’s atmosphere that has been observed for over 150 years.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-solar-system-34","question":"The dwarf planet Pluto lies in which region of the Solar System?","options":["The asteroid belt","The Kuiper belt","The Oort cloud","Between Jupiter and Saturn"],"answer":1,"explanation":"Pluto is the best-known member of the Kuiper belt, a ring of icy bodies beyond Neptune; the Oort cloud lies much farther out.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-solar-system-35","question":"Titan, the only moon known to have a thick nitrogen-rich atmosphere, orbits:","options":["Jupiter","Neptune","Uranus","Saturn"],"answer":3,"explanation":"Titan is Saturn’s largest moon; its dense atmosphere is mostly nitrogen with methane clouds and lakes.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-solar-system-36","question":"Phobos and Deimos are the two natural satellites of:","options":["Mars","Venus","Mercury","Neptune"],"answer":0,"explanation":"Mars has two small, irregular moons, Phobos and Deimos; Venus and Mercury have none.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-solar-system-37","question":"Sunlight takes approximately how long to reach the Earth?","options":["8 minutes 20 seconds","1 minute 20 seconds","80 minutes","8 seconds"],"answer":0,"explanation":"Earth is about 150 million km from the Sun; at 3 × 10⁸ m/s light covers that distance in roughly 500 s, i.e. about 8 min 20 s.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-solar-system-38","question":"The “Goldilocks zone” of a star is the region where:","options":["Asteroids are most concentrated","Liquid water can exist on a planet’s surface","Comets originate","The star’s magnetic field is strongest"],"answer":1,"explanation":"The habitable (Goldilocks) zone is the band of distances where a planet is neither too hot nor too cold for liquid water; Earth lies in the Sun’s habitable zone.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-solar-system-39","question":"Io, the most volcanically active body in the Solar System, is a moon of:","options":["Saturn","Jupiter","Neptune","Mars"],"answer":1,"explanation":"Io is one of Jupiter’s four Galilean moons; tidal heating by Jupiter drives its hundreds of active volcanoes.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-solar-system-40","question":"Halley’s Comet returns to the inner Solar System roughly once every:","options":["11 years","33 years","76 years","150 years"],"answer":2,"explanation":"Halley’s Comet has a period of about 75–76 years; it last appeared in 1986 and is expected again in 2061.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-solar-system-41","question":"Ceres, the largest object in the asteroid belt, is officially classified as a:","options":["Comet","Dwarf planet","Meteoroid","Natural satellite"],"answer":1,"explanation":"Since the IAU definition of 2006, Ceres is a dwarf planet, the only one in the asteroid belt; Pluto, Eris, Haumea and Makemake are the others.","difficulty":"hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-solar-system-42","question":"Which planet has the highest escape velocity?","options":["Saturn","Earth","Neptune","Jupiter"],"answer":3,"explanation":"Jupiter’s huge mass gives it an escape velocity of about 59.5 km/s, compared with 11.2 km/s for Earth and about 35 km/s for Saturn.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-solar-system-43","question":"The Solar System lies in which arm of the Milky Way galaxy?","options":["Perseus arm","Orion arm","Sagittarius arm","Norma arm"],"answer":1,"explanation":"The Sun sits on the inner edge of the Orion (Orion–Cygnus) arm, a minor spiral arm about 26,000 light-years from the galactic centre.","difficulty":"hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-solar-system-44","question":"Triton, a large moon that orbits its planet in the retrograde direction, belongs to:","options":["Uranus","Saturn","Neptune","Jupiter"],"answer":2,"explanation":"Triton is Neptune’s largest moon and the only large moon with a retrograde orbit, suggesting it was captured from the Kuiper belt.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-solar-system-45","question":"Mercury completes one rotation on its axis in about:","options":["24 hours","59 Earth days","88 Earth days","243 Earth days"],"answer":1,"explanation":"Mercury rotates once in about 58.6 Earth days and orbits the Sun in 88 days (a 3:2 spin–orbit resonance); 243 days is the rotation period of Venus.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-solar-system-46","question":"According to Kepler’s second law, a planet moves fastest in its orbit when it is:","options":["Farthest from the Sun","Nearest to the Sun","Crossing the ecliptic","At the equinox"],"answer":1,"explanation":"Kepler’s law of areas means a planet sweeps equal areas in equal times, so its speed is greatest at perihelion (nearest the Sun) and least at aphelion.","difficulty":"hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-solar-system-47","question":"Among the planets, the one with the highest albedo (reflecting the largest fraction of sunlight) is:","options":["Earth","Mars","Venus","Mercury"],"answer":2,"explanation":"Venus’s unbroken cover of sulphuric-acid clouds reflects about 70–75% of sunlight, which is why it is the brightest planet in our sky; Mercury reflects only about 12%.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-solar-system-48","question":"How many of these statements are correct? I. Jupiter has the strongest magnetic field of all the planets. II. Saturn is the only planet with rings. III. Uranus was discovered by William Herschel in 1781. IV. Mars has two natural satellites.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, III and IV are correct. II is wrong: all four giant planets (Jupiter, Saturn, Uranus, Neptune) have ring systems; Saturn’s are simply the most prominent.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-solar-system-49","question":"Assertion (A): Venus is hotter than Mercury even though it is farther from the Sun. Reason (R): Venus has a dense carbon-dioxide atmosphere that traps heat through a runaway greenhouse effect.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Venus’s surface stays near 465 °C day and night because its thick CO₂ atmosphere (about 92 times Earth’s pressure) traps heat, whereas airless Mercury radiates heat away quickly.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-solar-system-50","question":"Match the moon with its planet: 1. Titan 2. Europa 3. Triton 4. Phobos; a. Mars b. Neptune c. Saturn d. Jupiter","options":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-c, 2-b, 3-d, 4-a","1-b, 2-d, 3-c, 4-a"],"answer":0,"explanation":"Titan orbits Saturn, Europa is a Galilean moon of Jupiter, Triton is Neptune’s retrograde moon and Phobos is the larger moon of Mars.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-solar-system-51","question":"A planet takes 8 Earth years to orbit the Sun. By Kepler’s third law, its mean distance from the Sun is about:","options":["2 AU","4 AU","8 AU","16 AU"],"answer":1,"explanation":"T² = a³ (T in years, a in AU): 8² = 64 = a³, so a = 4 AU. Choosing 8 AU ignores the square–cube relation.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-solar-system-52","question":"Which of the following planets does NOT have a ring system?","options":["Uranus","Neptune","Mars","Jupiter"],"answer":2,"explanation":"Jupiter, Saturn, Uranus and Neptune all have rings (Jupiter’s and Neptune’s are faint). Mars, a terrestrial planet, has no rings.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-solar-system-53","question":"How many of these statements about the Earth are correct? I. Earth moves around the Sun at about 30 km/s. II. Earth’s sidereal rotation period is exactly 24 hours. III. Earth is the densest planet in the Solar System. IV. Earth’s mean distance from the Sun is about 150 million km.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, III and IV are correct (orbital speed ≈ 29.8 km/s; density 5.51 g/cm³ is the highest). II is wrong: the sidereal day is about 23 h 56 min; 24 h is the solar day.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-solar-system-54","question":"Arrange these bodies in the order in which they were discovered, earliest first: 1. Neptune 2. Uranus 3. Pluto 4. Ceres","options":["2, 4, 1, 3","2, 1, 4, 3","4, 2, 1, 3","2, 1, 3, 4"],"answer":0,"explanation":"Uranus was found in 1781 (Herschel), Ceres in 1801 (Piazzi), Neptune in 1846 (Galle, from Le Verrier’s prediction) and Pluto in 1930 (Tombaugh).","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-solar-system-55","question":"How many of these statements about the Sun are correct? I. The Sun is a G-type main-sequence star. II. The Sun produces its energy by nuclear fission. III. The photosphere is the visible surface of the Sun. IV. The corona is far hotter than the photosphere.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, III and IV are correct: the corona reaches over a million kelvin while the photosphere is about 5,800 K. II is wrong because the Sun’s energy comes from nuclear fusion of hydrogen into helium.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-solar-system-56","question":"Which planet completed its first full orbit of the Sun since its discovery only in 2011?","options":["Uranus","Neptune","Pluto","Saturn"],"answer":1,"explanation":"Neptune was discovered in 1846 and takes about 165 years to orbit the Sun, so it finished its first observed orbit in July 2011; Uranus (84-year orbit, found 1781) had done so long before.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-solar-system-57","question":"Match the region with the body associated with it: 1. Oort cloud 2. Kuiper belt 3. Main asteroid belt 4. Trojan asteroids; a. Ceres b. Jupiter’s orbit c. Long-period comets d. Pluto","options":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-b, 2-d, 3-a, 4-c"],"answer":0,"explanation":"Long-period comets come from the distant Oort cloud, Pluto lies in the Kuiper belt, Ceres is the largest body of the main belt, and the Trojans share Jupiter’s orbit at its Lagrange points.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-solar-system-58","question":"How many of these statements are correct? I. Titan is larger than the planet Mercury. II. Ganymede is larger than the planet Mercury. III. Earth’s Moon is the fifth-largest moon in the Solar System. IV. Europa is larger than Earth’s Moon.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct: Ganymede (5,268 km) and Titan (5,150 km) both exceed Mercury (4,880 km), and the Moon ranks fifth after Ganymede, Titan, Callisto and Io. IV is wrong: Europa (3,120 km) is smaller than the Moon (3,474 km).","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-solar-system-59","question":"Assertion (A): A sidereal day on Venus is longer than its year. Reason (R): Venus rotates once in about 243 Earth days but completes an orbit of the Sun in about 225 Earth days.","options":["A is true but R is false","Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is false but R is true"],"answer":1,"explanation":"Because the rotation period (243 days) exceeds the orbital period (225 days), one spin takes longer than one orbit; the slow retrograde rotation stated in R is exactly the reason.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id": "geo-solar-system-60", "question": "Since the 2006 decision of the International Astronomical Union, how many planets does the Solar System have?", "options": ["7", "8", "9", "10"], "answer": 1, "explanation": "There are eight planets: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus and Neptune. The count of nine included Pluto, which was reclassified as a dwarf planet in 2006.", "difficulty": "easy", "source": "SSC CHSL · RRB Group D"},
  {"id": "geo-solar-system-61", "question": "The mean distance between the Earth and the Sun, called one astronomical unit (AU), is about:", "options": ["384,400 km", "15 million km", "150 million km", "1.5 billion km"], "answer": 2, "explanation": "1 AU ≈ 1.5 × 10⁸ km, i.e. about 150 million km. 384,400 km is the Earth–Moon distance.", "difficulty": "easy", "source": "SSC GD · RRB Group D"},
  {"id": "geo-solar-system-62", "question": "Mars looks reddish because its surface rocks and dust are rich in:", "options": ["Sulphur", "Copper sulphate", "Carbon dust", "Iron oxide"], "answer": 3, "explanation": "Iron oxide (rust) in the Martian soil and dust gives the planet its red colour, hence the name “Red Planet”.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-solar-system-63", "question": "In which year did the International Astronomical Union reclassify Pluto as a dwarf planet?", "options": ["2001", "2011", "2006", "1996"], "answer": 2, "explanation": "At its Prague General Assembly in August 2006 the IAU defined a planet, and Pluto, which has not cleared its orbital neighbourhood, became a dwarf planet.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-solar-system-64", "question": "The Earth’s axis of rotation is tilted from the perpendicular to its orbital plane by about:", "options": ["0°", "23.5°", "66.5°", "90°"], "answer": 1, "explanation": "The axial tilt is about 23.5° (23.44°) from the perpendicular. 66.5° is the angle the axis makes with the orbital plane itself, a common trap.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-solar-system-65", "question": "Among the outer planets, which two are classed as “ice giants” rather than gas giants?", "options": ["Jupiter and Saturn", "Saturn and Uranus", "Jupiter and Neptune", "Uranus and Neptune"], "answer": 3, "explanation": "Uranus and Neptune contain a large share of “ices” (water, ammonia, methane) beneath thinner hydrogen–helium envelopes; Jupiter and Saturn are the gas giants.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-solar-system-66", "question": "A piece of rock from space that survives its passage through the atmosphere and lands on the Earth’s surface is called a:", "options": ["Meteorite", "Meteoroid", "Asteroid", "Comet"], "answer": 0, "explanation": "In space it is a meteoroid, the streak of light in the sky is a meteor, and the piece that reaches the ground is a meteorite.", "difficulty": "moderate", "source": "RRB NTPC · SSC CHSL"},
  {"id": "geo-solar-system-67", "question": "The time the Moon takes to complete one revolution around the Earth measured against the distant stars (the sidereal month) is about:", "options": ["29.5 days", "27.3 days", "24.8 days", "30.4 days"], "answer": 1, "explanation": "The sidereal month is about 27.3 days. The synodic month (new moon to new moon) is longer, about 29.5 days, because the Earth has moved along its orbit in the meantime.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-68", "question": "Voyager 1 became the first human-made object to enter interstellar space in:", "options": ["1990", "2004", "2012", "2020"], "answer": 2, "explanation": "Voyager 1, launched in 1977, crossed the heliopause in August 2012. Voyager 2 followed in 2018.", "difficulty": "hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "geo-solar-system-69", "question": "Neptune was discovered in 1846 mainly as a result of:", "options": ["Galileo’s telescope observations of its rings", "Mathematical predictions based on irregularities in the orbit of Uranus", "Photographs taken by the Voyager 2 probe", "Radio signals detected from the planet"], "answer": 1, "explanation": "Le Verrier (and Adams) predicted its position from the unexplained perturbations of Uranus’s orbit, and Galle found it close to that spot; it was the first planet found by calculation.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-70", "question": "India’s solar observatory Aditya-L1 is placed in a halo orbit around the Lagrange point L1, which lies at about what distance from the Earth?", "options": ["15 million km", "384,400 km", "150 million km", "1.5 million km"], "answer": 3, "explanation": "L1 is about 1.5 million km from the Earth towards the Sun, roughly 1% of the Earth–Sun distance, so the Sun can be watched without eclipses.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-71", "question": "The outermost layer of the Sun’s atmosphere, seen as a pearly glow around the Moon during a total solar eclipse, is the:", "options": ["Photosphere", "Chromosphere", "Corona", "Core"], "answer": 2, "explanation": "The corona is the outermost layer and becomes visible when the Moon blocks the bright photosphere; the chromosphere is the thin reddish layer just above the photosphere.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-solar-system-72", "question": "Which planet has the fastest winds measured in the Solar System, exceeding 2,000 km/h?", "options": ["Neptune", "Jupiter", "Saturn", "Mars"], "answer": 0, "explanation": "Voyager 2 measured winds of about 2,100 km/h on Neptune, the fastest of any planet, even though it is the farthest from the Sun.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-solar-system-73", "question": "Sunspots appear dark on the Sun’s surface because they are:", "options": ["Hotter than the surrounding regions", "Holes through which the core is visible", "Shadows cast by the inner planets", "Cooler than the surrounding photosphere"], "answer": 3, "explanation": "Sunspots are regions of intense magnetic activity about 1,500 °C cooler than the surrounding photosphere, so they look dark by contrast; their number follows an 11-year cycle.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-74", "question": "How many of these statements are correct? I. The IAU recognises five dwarf planets: Ceres, Pluto, Eris, Haumea and Makemake. II. Ceres is the only dwarf planet in the main asteroid belt. III. Eris is more massive than Pluto. IV. Pluto has no natural satellite.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct (Eris is about 27% more massive than Pluto though slightly smaller in diameter). IV is wrong: Pluto has five known moons, the largest being Charon.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-75", "question": "Assertion (A): The same face of the Moon is always seen from the Earth. Reason (R): The Moon takes the same time to rotate once on its axis as it takes to revolve once around the Earth.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "The Moon is tidally locked: its rotation period equals its orbital period (about 27.3 days), so one hemisphere always faces the Earth. R correctly explains A.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-76", "question": "Match the mission with its main target: 1. Mangalyaan 2. Juno 3. New Horizons 4. Cassini; a. Saturn b. Pluto c. Jupiter d. Mars", "options": ["1-c, 2-d, 3-a, 4-b", "1-d, 2-b, 3-c, 4-a", "1-d, 2-c, 3-b, 4-a", "1-a, 2-c, 3-b, 4-d"], "answer": 2, "explanation": "Mangalyaan (ISRO) went to Mars, Juno orbits Jupiter, New Horizons flew past Pluto in 2015 and Cassini studied Saturn until 2017.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-77", "question": "Assertion (A): Pluto is no longer counted as one of the planets of the Solar System. Reason (R): Pluto is not nearly round in shape.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true. R is false: Pluto is massive enough to be nearly round. It failed the IAU test because it has not cleared the neighbourhood of its orbit (the Kuiper belt).", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-78", "question": "How many of these statements are correct? I. Comets are made largely of ice, dust and rock. II. A comet carries its tail throughout its orbit, even far from the Sun. III. Most meteors burn up in the mesosphere. IV. Halley’s Comet was last seen from the inner Solar System in 1986.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, III and IV are correct. II is wrong: the tail forms only when the comet nears the Sun and its ices vaporise; far out it is just a frozen nucleus.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-solar-system-79", "question": "Arrange these bodies in increasing order of diameter: 1. Mercury 2. Pluto 3. Ganymede 4. Earth’s Moon", "options": ["2, 4, 1, 3", "4, 2, 1, 3", "2, 4, 3, 1", "4, 2, 3, 1"], "answer": 0, "explanation": "Pluto (about 2,377 km) < Moon (about 3,475 km) < Mercury (about 4,880 km) < Ganymede (about 5,268 km). The trap is that the moon Ganymede is larger than the planet Mercury.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-80", "question": "A planet has twice the radius of the Earth and the same average density. If the Earth’s escape velocity is 11.2 km/s, the planet’s escape velocity is:", "options": ["11.2 km/s", "15.8 km/s", "44.8 km/s", "22.4 km/s"], "answer": 3, "explanation": "vₑ = √(2GM/R) and M ∝ ρR³, so vₑ ∝ R√ρ. With the same density and double the radius, vₑ doubles: 2 × 11.2 = 22.4 km/s.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-solar-system-81", "question": "A body weighs 600 N on the Earth (g = 10 m/s²). If gravity on the Moon is one-sixth of that on the Earth, its mass and weight on the Moon are:", "options": ["10 kg and 100 N", "60 kg and 100 N", "60 kg and 600 N", "10 kg and 600 N"], "answer": 1, "explanation": "Mass = 600 ÷ 10 = 60 kg and does not change with place. Weight on the Moon = 600 ÷ 6 = 100 N.", "difficulty": "very-hard", "source": "SSC CHSL · RRB Group D"},
  {"id": "geo-solar-system-82", "question": "Which of the following is NOT a moon of Jupiter?", "options": ["Io", "Europa", "Enceladus", "Callisto"], "answer": 2, "explanation": "Io, Europa, Ganymede and Callisto are the four Galilean moons of Jupiter. Enceladus, with its icy water plumes, is a moon of Saturn.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-solar-system-83", "question": "How many of these statements about the Moon are correct? I. Its mean distance from the Earth is about 384,400 km. II. Its surface gravity is about one-sixth of the Earth’s. III. It has a thick atmosphere. IV. Its far side never receives sunlight.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and II are correct. The Moon has practically no atmosphere, and the far side gets as much sunlight as the near side; it is only hidden from the Earth, not dark.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-84", "question": "Arrange these Indian space events in chronological order: 1. Mangalyaan enters orbit around Mars 2. Launch of Chandrayaan-1 3. Launch of Aditya-L1 4. Chandrayaan-3 lands near the lunar south pole", "options": ["2, 1, 3, 4", "2, 1, 4, 3", "1, 2, 4, 3", "2, 4, 1, 3"], "answer": 1, "explanation": "Chandrayaan-1 was launched in October 2008, Mangalyaan reached Mars orbit on 24 September 2014, Chandrayaan-3 landed on 23 August 2023 and Aditya-L1 was launched on 2 September 2023.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-85", "question": "Who first observed the four largest moons of Jupiter, in 1610?", "options": ["Nicolaus Copernicus", "Galileo Galilei", "Johannes Kepler", "Isaac Newton"], "answer": 1, "explanation": "Galileo Galilei saw Io, Europa, Ganymede and Callisto through his telescope in January 1610; they are called the Galilean moons. Kepler gave the laws of planetary motion and Copernicus the heliocentric model.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "geo-solar-system-86", "question": "A lunar eclipse can occur only on a:", "options": ["First-quarter day", "New moon day", "Any day of the month", "Full moon night"], "answer": 3, "explanation": "In a lunar eclipse the Earth lies between the Sun and the Moon, which is exactly the full-moon position. A solar eclipse, in contrast, needs the Moon between the Sun and the Earth, which happens only at new moon.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "geo-solar-system-87", "question": "The large, dark, smooth plains on the Moon that can be seen with the naked eye are called:", "options": ["Highlands", "Craters", "Rilles", "Maria"], "answer": 3, "explanation": "Maria (Latin for ‘seas’) are vast plains of solidified basaltic lava; dark basalt reflects less sunlight, so they look darker than the bright, cratered highlands. Early astronomers mistook them for seas.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "geo-solar-system-88", "question": "Solar and lunar eclipses do not occur every month mainly because:", "options": ["The Earth’s axis is tilted by 23.5°", "The Moon’s orbit is a perfect circle", "The Moon rotates once on its axis every month", "The Moon’s orbit is inclined about 5° to the plane of the Earth’s orbit"], "answer": 3, "explanation": "Because of the 5° tilt, the Moon at new or full moon usually passes above or below the Sun–Earth line; eclipses happen only when new or full moon falls near the nodes where the two orbits cross. The Earth’s axial tilt causes the seasons, not this.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-89", "question": "The temperature of the Sun’s visible surface, the photosphere, is about:", "options": ["15 million °C", "1 million °C", "5,500 °C", "1,500 °C"], "answer": 2, "explanation": "The photosphere is about 5,500 °C (roughly 5,800 K). The corona reaches more than a million degrees and the core about 15 million degrees, so those options describe other layers.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "geo-solar-system-90", "question": "The auroras (northern and southern lights) are caused by:", "options": ["Meteors burning up in the mesosphere", "Charged particles from the Sun striking gases of the upper atmosphere near the magnetic poles", "Lightning in the stratosphere", "Sunlight reflected from polar ice"], "answer": 1, "explanation": "Charged particles of the solar wind are guided by the Earth’s magnetic field towards the polar regions, where they excite oxygen and nitrogen atoms that glow green, red or violet. That is why auroras are seen mostly at high latitudes.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-91", "question": "Mars rotates once on its axis in about:", "options": ["24 hours 37 minutes", "16 hours", "59 Earth days", "10 hours"], "answer": 0, "explanation": "Mars spins once in about 24 h 37 min, so its day is very close to the Earth’s. About 10 hours is Jupiter, about 16 hours is Neptune and 59 days is Mercury.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "geo-solar-system-92", "question": "As of 2025, which planet has the largest number of confirmed moons?", "options": ["Neptune", "Saturn", "Uranus", "Jupiter"], "answer": 1, "explanation": "In March 2025 astronomers confirmed 128 more small moons of Saturn, taking its total to 274, far more than Jupiter’s count of under 100. The lead has switched before as new discoveries are announced, which is why the year matters.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "geo-solar-system-93", "question": "Pluto’s largest moon, about half the diameter of Pluto itself, is:", "options": ["Charon", "Nix", "Triton", "Titania"], "answer": 0, "explanation": "Charon is about 1,212 km across against Pluto’s 2,377 km, so the two orbit a common centre lying outside Pluto. Triton belongs to Neptune, Titania to Uranus, and Nix is one of Pluto’s small moons.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "geo-solar-system-94", "question": "Around what time does a first-quarter Moon cross the meridian, that is, stand highest in the sky?", "options": ["About 6 pm (sunset)", "About 6 am (sunrise)", "Midnight", "Noon"], "answer": 0, "explanation": "At first quarter the Moon is 90° east of the Sun, so it rises around noon, is highest around sunset and sets around midnight. The full Moon, opposite the Sun, is the one that is highest at midnight.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-95", "question": "The synodic month (new moon to new moon, about 29.5 days) is longer than the sidereal month (about 27.3 days) because:", "options": ["The Moon slows down near apogee", "The Earth moves along its orbit, so the Moon must travel about two more days to line up with the Sun again", "The Earth’s rotation is gradually slowing", "The Moon’s orbit is tilted by 5°"], "answer": 1, "explanation": "In 27.3 days the Moon completes one turn relative to the stars, but meanwhile the Earth has moved about 27° around the Sun, so the Moon needs roughly 2.2 extra days to return to the same phase. The orbital tilt affects eclipses, not the month length.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-96", "question": "An annular (‘ring of fire’) solar eclipse occurs when:", "options": ["The Moon is near perigee and looks largest", "The Earth is at aphelion, so the Sun looks largest", "The Moon is near apogee and its disc looks too small to cover the Sun completely", "Only the Earth’s penumbra falls on the Moon"], "answer": 2, "explanation": "Near apogee the Moon appears slightly smaller than the Sun, so a bright ring is left around it. The Sun actually looks smallest at aphelion, and the Earth’s shadow on the Moon describes a lunar, not solar, eclipse.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-97", "question": "The Kirkwood gaps are:", "options": ["The empty space between the Kuiper belt and the Oort cloud", "Zones of the asteroid belt nearly empty of asteroids because of orbital resonances with Jupiter", "Gaps in Saturn’s rings cleared by shepherd moons", "Dark lanes seen in the Sun’s corona"], "answer": 1, "explanation": "Asteroids whose periods would be a simple fraction of Jupiter’s (such as 1/3 or 2/5) receive repeated tugs and are cleared out, leaving gaps in the belt. Gaps in Saturn’s rings, such as the Cassini Division, are a different feature.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-98", "question": "The particles of Saturn’s rings have not gathered together to form a moon mainly because:", "options": ["They lie within Saturn’s Roche limit, where tidal forces are stronger than their mutual gravity", "They are made of ice", "Saturn’s magnetic field keeps them apart", "They move faster than Saturn’s escape velocity"], "answer": 0, "explanation": "Inside the Roche limit the difference in Saturn’s pull across a clump exceeds the gravity holding the clump together, so it is torn apart. Being icy does not prevent clumping, and particles faster than escape velocity would leave Saturn altogether.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-99", "question": "India’s Mars Orbiter Mission (Mangalyaan) was launched on 5 November 2013 by:", "options": ["PSLV-C25", "PSLV-C11", "GSLV-F10", "GSLV Mk III"], "answer": 0, "explanation": "PSLV-C25 launched Mangalyaan from Sriharikota, and it entered Mars orbit on 24 September 2014. PSLV-C11 launched Chandrayaan-1 in 2008, while the GSLV Mk III (LVM3) launched Chandrayaan-2 and Chandrayaan-3.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-100", "question": "The spot where Chandrayaan-3’s Vikram lander touched down on the Moon in August 2023 has been named:", "options": ["Vikram Sarabhai point", "Jawahar Sthal", "Tiranga point", "Shiv Shakti point"], "answer": 3, "explanation": "The landing site was named Shiv Shakti point, and 23 August, the landing date, was declared National Space Day. Tiranga point marks where Chandrayaan-2’s lander crashed in 2019, and Jawahar Sthal is where Chandrayaan-1’s Moon Impact Probe struck in 2008.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-101", "question": "Uranus and Neptune look bluish-green mainly because:", "options": ["Their oceans of liquid water reflect blue light", "Their rings scatter blue light", "They are hotter than the other giant planets", "Methane in their atmospheres absorbs red light and reflects blue-green light"], "answer": 3, "explanation": "Methane absorbs the red part of sunlight, so the light scattered back from their upper atmospheres is blue-green. They have no surface oceans, they are among the coldest planets, and their faint rings play no part.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-102", "question": "A planet has twice the mass and twice the radius of the Earth. A person who weighs 600 N on the Earth would weigh there:", "options": ["300 N", "600 N", "150 N", "1,200 N"], "answer": 0, "explanation": "Surface gravity g ∝ M/R², so g changes by 2/2² = 1/2. The weight becomes 600 × 1/2 = 300 N; the mass of the person does not change.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "geo-solar-system-103", "question": "How many of these statements about eclipses are correct? I. A lunar eclipse can be seen at the same time from the whole night side of the Earth. II. A total solar eclipse is visible only along a narrow path on the Earth. III. During a total lunar eclipse the Moon often looks reddish because the Earth’s atmosphere bends red light onto it. IV. A solar eclipse can occur on a full moon day.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct: the Earth’s shadow covers the whole Moon, but the Moon’s small shadow sweeps only a narrow track across the Earth, and red light refracted by the Earth’s atmosphere tints the eclipsed Moon. IV is wrong because a solar eclipse needs the new moon.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-104", "question": "Arrange these space events in chronological order: 1. NASA’s DART spacecraft strikes the asteroid moon Dimorphos 2. The Philae lander touches down on comet 67P 3. OSIRIS-REx returns its sample of asteroid Bennu to the Earth 4. New Horizons flies past Pluto", "options": ["2, 4, 1, 3", "4, 2, 3, 1", "4, 2, 1, 3", "2, 4, 3, 1"], "answer": 0, "explanation": "Philae landed in November 2014, New Horizons passed Pluto in July 2015, DART hit Dimorphos in September 2022 and the OSIRIS-REx capsule landed in September 2023.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-105", "question": "Match the mission with its target: 1. Hayabusa2 2. Rosetta 3. DART 4. Dawn; a. Vesta and Ceres b. Dimorphos c. Comet 67P/Churyumov–Gerasimenko d. Asteroid Ryugu", "options": ["1-c, 2-d, 3-b, 4-a", "1-b, 2-c, 3-d, 4-a", "1-d, 2-c, 3-a, 4-b", "1-d, 2-c, 3-b, 4-a"], "answer": 3, "explanation": "Japan’s Hayabusa2 sampled Ryugu, ESA’s Rosetta orbited comet 67P, NASA’s DART deflected Dimorphos, and NASA’s Dawn orbited Vesta and then Ceres.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-106", "question": "Assertion (A): Jupiter radiates more energy into space than it receives from the Sun. Reason (R): Jupiter is still slowly contracting under its own gravity, which releases heat from its interior.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Jupiter gives out roughly 1.6–2 times the energy it absorbs; the extra comes from heat left over from its formation and from slow gravitational contraction, which converts potential energy into heat. So R explains A.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-107", "question": "A space probe is 5 AU from the Earth. Taking 1 AU = 1.5 × 10⁸ km and the speed of light as 3 × 10⁵ km/s, how long does it take for a command to reach the probe and its reply to come back?", "options": ["41 min 40 s", "25 min", "8 min 20 s", "83 min 20 s"], "answer": 3, "explanation": "Distance = 5 × 1.5 × 10⁸ = 7.5 × 10⁸ km; one way takes 7.5 × 10⁸ ÷ 3 × 10⁵ = 2,500 s = 41 min 40 s. The round trip is twice that, 5,000 s = 83 min 20 s; 41 min 40 s is only the one-way time.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-108", "question": "How many of these statements about the Sun are correct? I. The temperature at its core is about 15 million K. II. Energy produced in the core takes many thousands of years to reach the surface. III. Nuclear fusion takes place mainly in the convective zone. IV. The Sun rotates faster at its equator than near its poles.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct: photons random-walk through the dense radiative zone for thousands of years or more, and the equator turns in about 25 days against about 35 near the poles. III is wrong because fusion occurs only in the core.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-109", "question": "Match the layer of the Sun with its feature: 1. Core 2. Photosphere 3. Chromosphere 4. Corona; a. Outermost layer and source of the solar wind b. Hydrogen fuses into helium c. Thin reddish layer seen just at the start and end of totality d. Visible surface on which sunspots appear", "options": ["1-b, 2-d, 3-a, 4-c", "1-b, 2-d, 3-c, 4-a", "1-b, 2-c, 3-d, 4-a", "1-d, 2-b, 3-c, 4-a"], "answer": 1, "explanation": "Fusion happens in the core; the photosphere is the visible surface with sunspots; the chromosphere flashes red for a moment during totality; and the hot corona extends far out and streams away as the solar wind.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-110", "question": "Which of the following statements about Pluto is NOT correct?", "options": ["Its orbit is more eccentric than that of any of the eight planets", "It is larger than the Earth’s Moon", "It has five known moons", "It was discovered by Clyde Tombaugh in 1930"], "answer": 1, "explanation": "Pluto is about 2,377 km across, smaller than the Moon’s 3,474 km. It was found by Clyde Tombaugh in 1930, has five known moons (Charon, Nix, Hydra, Kerberos, Styx), and its eccentricity (about 0.25) exceeds Mercury’s (about 0.21).", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-111", "question": "How many of these statements are correct? I. Spring tides occur at new moon and full moon. II. Neap tides occur at the first and last quarter phases. III. The tidal range is greatest during neap tides. IV. The Sun’s tide-raising force on the Earth is about twice that of the Moon.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and II are correct. When the Sun and Moon are in line (new and full moon) their pulls add up to give spring tides with the greatest range; at the quarters they act at right angles and give neap tides with the least range. The Moon’s tidal force is about twice the Sun’s because it is so much closer.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-112", "question": "Assertion (A): Mars has seasons similar to those of the Earth. Reason (R): Mars has practically no tilt of its axis.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true but R is false. Mars’s axis is tilted about 25°, close to the Earth’s 23.5°, and that tilt is what gives it seasons; its seasons last about twice as long because its year is about 687 days.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-113", "question": "Arrange these moons in decreasing order of diameter: 1. Io 2. Titan 3. Europa 4. Callisto", "options": ["2, 4, 3, 1", "2, 1, 4, 3", "4, 2, 1, 3", "2, 4, 1, 3"], "answer": 3, "explanation": "Titan is about 5,150 km across, Callisto about 4,820 km, Io about 3,640 km and Europa about 3,120 km. Europa is the smallest of the four and is even smaller than the Earth’s Moon.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-solar-system-114", "question": "How many of these statements about Lagrange points are correct? I. A system of two large bodies, such as the Sun and the Earth, has five Lagrange points. II. The Sun–Earth L1 point lies between the Sun and the Earth. III. The James Webb Space Telescope orbits around the Sun–Earth L2 point. IV. The L4 and L5 points are stable, which is why Trojan asteroids collect there.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. L1 (used by Aditya-L1 and SOHO) is sunward of the Earth and L2 (used by JWST) lies on the far side, both about 1.5 million km away; L1, L2 and L3 are unstable, while L4 and L5, 60° ahead of and behind the smaller body, are stable and gather Trojan asteroids.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
];

export default questions;
